import {
  BitmapFont,
  Cache,
  Assets as PixiAssets,
  Rectangle,
  Texture,
  bitmapFontTextParser,
  bitmapFontXMLStringParser,
} from 'pixi.js';
import { didYouMean } from './suggest';

/**
 * Every asset file of the game, generated by the CLI: project path → URL. In release builds,
 * small images are packed into atlases and listed in `atlases` instead of `files`.
 */
export interface AssetManifest {
  /** Project path (`assets/sprites/hero.png`) → URL the browser fetches. */
  files: Record<string, string>;
  /** Images packed into an atlas by a release build: project path → atlas and rectangle. */
  atlases?: Record<
    string,
    {
      /** URL of the atlas image. */
      url: string;
      /** Rectangle of the image inside the atlas: `[x, y, width, height]` in pixels. */
      frame: [number, number, number, number];
    }
  >;
}

const ALIASES: Record<string, string> = {
  '@assets/': 'assets/',
  '@objects/': 'objects/',
  '@models/': 'models/',
  '@stories/': 'stories/',
  '@ui/': 'ui/',
  '@modules/': 'modules/',
};

export const IMAGE_EXTENSIONS = ['png', 'jpg', 'jpeg', 'webp', 'avif', 'gif', 'svg'];
export const AUDIO_EXTENSIONS = ['ogg', 'm4a', 'mp3', 'wav', 'opus', 'webm', 'aac', 'flac'];
export const FONT_EXTENSIONS = ['woff2', 'woff', 'ttf', 'otf'];
export const VIDEO_EXTENSIONS = ['mp4', 'webm', 'mov'];

export function extension(path: string): string {
  const dot = path.lastIndexOf('.');
  return dot < 0 ? '' : path.slice(dot + 1).toLowerCase();
}

/**
 * File name without folder and extension: the asset's key (`assets/sfx/coin.ogg` → `coin`). Game
 * code names sounds, sprites and animations by this key instead of their full path.
 *
 * @example
 * ```ts
 * import { assetKey } from '@blacklight/core';
 *
 * assetKey('assets/sfx/coin.ogg'); // 'coin'
 * ```
 */
export function assetKey(path: string): string {
  const file = path.slice(path.lastIndexOf('/') + 1);
  const dot = file.indexOf('.');
  return dot < 0 ? file : file.slice(0, dot);
}

/** Normalizes `a/./b/../c` and removes leading `./` or `/`. */
function normalize(path: string): string {
  const out: string[] = [];
  for (const part of path.split('/')) {
    if (part === '' || part === '.') continue;
    if (part === '..') out.pop();
    else out.push(part);
  }
  return out.join('/');
}

/**
 * Turns a path written in game code into a project path: `@assets/x` → `assets/x`, `./x` relative
 * to `baseDir`, `/x` from the project root.
 *
 * @example
 * ```ts
 * import { resolveProjectPath } from '@blacklight/core';
 *
 * resolveProjectPath('@assets/sfx/coin.ogg'); // 'assets/sfx/coin.ogg'
 * resolveProjectPath('./hero.png', 'objects/hero'); // 'objects/hero/hero.png'
 * ```
 */
export function resolveProjectPath(path: string, baseDir = ''): string {
  for (const [alias, dir] of Object.entries(ALIASES))
    if (path.startsWith(alias)) return normalize(dir + path.slice(alias.length));
  if (path.startsWith('/')) return normalize(path);
  return normalize(baseDir ? `${baseDir}/${path}` : path);
}

type Kind = 'image' | 'json' | 'audio' | 'font' | 'bitmap-font' | 'text' | 'other';

function kindOf(path: string): Kind {
  const ext = extension(path);
  if (IMAGE_EXTENSIONS.includes(ext)) return 'image';
  if (ext === 'json') return 'json';
  if (AUDIO_EXTENSIONS.includes(ext)) return 'audio';
  if (FONT_EXTENSIONS.includes(ext)) return 'font';
  if (ext === 'fnt') return 'bitmap-font';
  if (['txt', 'ink', 'csv', 'md'].includes(ext)) return 'text';
  return 'other';
}

/** Decodes audio files; provided by the audio manager. */
export type AudioDecoder = (path: string, url: string) => Promise<void>;

/**
 * Loads a file type core does not know (glTF models…). Gets the project path, its URL and the
 * store (to find related files); what it resolves is returned by `assets.get(path)`.
 */
export type AssetLoader = (path: string, url: string, assets: AssetStore) => Promise<unknown>;

/** Loaders added by packages, by lowercase extension. */
const loaders = new Map<string, AssetLoader>();

/**
 * Finds and loads the game's files. Loading puts them in a cache; sprites, sounds and texts then
 * read them synchronously. Each game has one, as `game.assets`; scenes load what they list in
 * `static assets` before `create()`.
 *
 * @example
 * ```ts
 * import { Scene } from '@blacklight/core';
 *
 * export default class Title extends Scene {
 *   create() {
 *     const level = this.game.assets.getJson<{ name: string }>('assets/levels/1.json');
 *     console.log(level.name, this.game.assets.has('assets/sfx/coin.ogg'));
 *   }
 * }
 * ```
 */
export class AssetStore {
  private readonly json = new Map<string, unknown>();
  private readonly text = new Map<string, string>();
  private readonly textures = new Map<string, Texture>();
  private readonly custom = new Map<string, unknown>();
  private readonly loading = new Map<string, Promise<void>>();
  private readonly loaded = new Set<string>();
  /** @internal Set by the audio manager. */
  decodeAudio: AudioDecoder | undefined;

  constructor(
    /** Every file of the game and its URL, as generated by the CLI. */
    readonly manifest: AssetManifest = { files: {} },
  ) {}

  /**
   * Teaches every asset store to load more file types. Packages call it when their module loads,
   * so only games (and scenes) that import them pay for the loader.
   *
   * @example
   * ```ts
   * AssetStore.registerLoader(['glb', 'gltf'], (path, url) => loadModel(url));
   * ```
   */
  static registerLoader(extensions: string[], loader: AssetLoader): void {
    for (const ext of extensions) loaders.set(ext.toLowerCase(), loader);
  }

  /** Every project path in the manifest. */
  get paths(): string[] {
    return [...Object.keys(this.manifest.files), ...Object.keys(this.manifest.atlases ?? {})];
  }

  /** Whether the game has a file at this project path (whether or not it is loaded). */
  has(path: string): boolean {
    return path in this.manifest.files || path in (this.manifest.atlases ?? {});
  }

  /** URL of a project path, `undefined` when it is not an asset (or packed in an atlas). */
  url(path: string): string | undefined {
    return this.manifest.files[path];
  }

  /**
   * Finds a file by key (`coin`) or path (`@assets/sfx/coin.ogg`, `./player.png`). Keys are looked
   * up in `preferDirs` first (the current scene), then everywhere.
   *
   * @throws Error naming close matches when nothing matches.
   */
  find(
    keyOrPath: string,
    options: { baseDir?: string; preferDirs?: string[]; extensions?: string[] } = {},
  ): string[] {
    const { baseDir, preferDirs = [], extensions } = options;
    const accept = (p: string) => !extensions || extensions.includes(extension(p));
    if (keyOrPath.includes('/') || keyOrPath.includes('.')) {
      const path = resolveProjectPath(keyOrPath, baseDir);
      if (this.has(path)) return [path];
      // A path without extension matches every format of that file (coin → coin.ogg, coin.m4a).
      const variants = this.paths.filter(
        (p) => p.slice(0, p.lastIndexOf('.')) === path && accept(p),
      );
      if (variants.length > 0) return variants;
      throw new Error(`No asset at "${path}".${didYouMean(path, this.paths)}`);
    }
    const matches = this.paths.filter((p) => assetKey(p) === keyOrPath && accept(p));
    if (matches.length === 0) {
      const keys = new Set(this.paths.filter(accept).map(assetKey));
      throw new Error(
        `No asset named "${keyOrPath}".${didYouMean(keyOrPath, keys)} Put the file under assets/ or the scene's assets/ folder.`,
      );
    }
    for (const dir of preferDirs) {
      const local = matches.filter((p) => p.startsWith(`${dir}/`));
      if (local.length > 0) return sameFile(local);
    }
    const global = matches.filter((p) => p.startsWith('assets/'));
    return sameFile(global.length > 0 ? global : matches);
  }

  /** Loads files into the cache. Already loaded files are skipped. */
  async load(
    paths: Iterable<string>,
    onProgress?: (done: number, total: number) => void,
  ): Promise<void> {
    const list = [...new Set(paths)];
    let done = 0;
    onProgress?.(0, list.length);
    await Promise.all(
      list.map(async (path) => {
        await this.loadOne(path);
        onProgress?.(++done, list.length);
      }),
    );
  }

  /** Whether the file at this project path is in the cache, so it can be read synchronously. */
  isLoaded(path: string): boolean {
    return this.loaded.has(path);
  }

  private loadOne(path: string): Promise<void> {
    if (this.loaded.has(path)) return Promise.resolve();
    let promise = this.loading.get(path);
    if (!promise) {
      promise = this.fetchOne(path).then(() => {
        this.loaded.add(path);
      });
      this.loading.set(path, promise);
    }
    return promise;
  }

  private async fetchOne(path: string): Promise<void> {
    const atlas = this.manifest.atlases?.[path];
    if (atlas) {
      const source = await PixiAssets.load<Texture>({
        src: atlas.url,
        parser: 'texture',
        data: { resolution: 1 },
      });
      const [x, y, width, height] = atlas.frame;
      this.textures.set(
        path,
        new Texture({ source: source.source, frame: new Rectangle(x, y, width, height) }),
      );
      return;
    }
    const url = this.manifest.files[path];
    if (!url) throw new Error(`No asset at "${path}".${didYouMean(path, this.paths)}`);
    switch (kindOf(path)) {
      case 'image':
        // Resolution 1: Pixi would read "@16x16" in a grid sheet's name as a 16x resolution suffix.
        this.textures.set(
          path,
          await PixiAssets.load<Texture>({ src: url, parser: 'texture', data: { resolution: 1 } }),
        );
        return;
      case 'json':
        this.json.set(path, await (await fetch(url)).json());
        return;
      case 'text':
        this.text.set(path, await (await fetch(url)).text());
        return;
      case 'audio':
        await this.decodeAudio?.(path, url);
        return;
      case 'bitmap-font':
        await this.loadBitmapFont(path, url);
        return;
      case 'font': {
        const face = new FontFace(assetKey(path), `url(${url})`);
        await face.load();
        document.fonts.add(face);
        return;
      }
      default: {
        const loader = loaders.get(extension(path));
        if (loader) this.custom.set(path, await loader(path, url, this));
        return;
      }
    }
  }

  /** Loads an AngelCode `.fnt` (text or XML) and its pages; `BitmapText` then uses its family. */
  private async loadBitmapFont(path: string, url: string): Promise<void> {
    const source = await (await fetch(url)).text();
    const data = bitmapFontTextParser.test(source)
      ? bitmapFontTextParser.parse(source)
      : bitmapFontXMLStringParser.parse(source);
    const dir = path.slice(0, path.lastIndexOf('/'));
    const pages = data.pages.map((page) => resolveProjectPath(page.file, dir));
    await this.load(pages);
    const font = new BitmapFont({ data, textures: pages.map((page) => this.texture(page)) });
    Cache.set(`${data.fontFamily}-bitmap`, font);
  }

  /**
   * Loaded texture of an image.
   * @throws Error when the image was not preloaded, with how to preload it.
   */
  texture(path: string): Texture {
    const texture = this.textures.get(path);
    if (!texture) throw notLoaded(path);
    return texture;
  }

  /** Loaded content of a JSON file. */
  getJson<T = unknown>(path: string): T {
    if (!this.json.has(path)) throw notLoaded(path);
    return this.json.get(path) as T;
  }

  /** What a registered loader made of a file (see {@link AssetStore.registerLoader}). */
  get<T = unknown>(path: string): T {
    if (!this.custom.has(path)) throw notLoaded(path);
    return this.custom.get(path) as T;
  }

  /** Loaded content of a text file. */
  getText(path: string): string {
    const value = this.text.get(path);
    if (value === undefined) throw notLoaded(path);
    return value;
  }
}

function notLoaded(path: string): Error {
  return new Error(
    `"${path}" is not loaded. List it in the scene's \`static assets\` (or the object's), or call \`await game.assets.load(['${path}'])\` first.`,
  );
}

/** Keeps the files of one name (`coin.ogg` + `coin.m4a`), refusing two different folders. */
function sameFile(paths: string[]): string[] {
  const stems = new Set(paths.map((p) => p.slice(0, p.lastIndexOf('.'))));
  if (stems.size > 1) {
    throw new Error(
      `Several assets are named "${assetKey(paths[0]!)}": ${paths.join(', ')}. Use a path instead of the name.`,
    );
  }
  return paths;
}
